15: pub fn assert_typed_ipc_error(error: vb_ipc::IpcError) -> bool {
16:     use vb_ipc::IpcError;
17:     matches!(
18:         error,
19:         IpcError::Full
20:             | IpcError::Disconnected
21:             | IpcError::PayloadTooLarge { .. }
22:             | IpcError::InvalidMagic { .. }
23:             | IpcError::UnsupportedVersion { .. }
24:             | IpcError::UnknownCommand(_)
25:             | IpcError::ReservedNonZero { .. }
26:             | IpcError::PayloadLengthMismatch { .. }
27:             | IpcError::HeaderEncodeFailed
28:             | IpcError::HeaderDecodeFailed
29:             | IpcError::PayloadLengthOutOfRange { .. }
30:             | IpcError::PayloadEncodeFailed
31:             | IpcError::PayloadDecodeFailed
32:             | IpcError::ResponseDecodeFailed
33:     )
34: }
