36: pub fn fuzz_ipc_frame(data: &[u8]) {
37:     use vb_ipc::frame::{decode_frame_header, decode_frame_payload};
38: 
39:     let Some(header_bytes) = data.get(..vb_ipc::IPC_HEADER_LEN) else {
40:         return;
41:     };
42: 
43:     let mut header = [0u8; vb_ipc::IPC_HEADER_LEN];
44:     header.copy_from_slice(header_bytes);
45: 
46:     let header_result = decode_frame_header(&header);
47: 
48:     if let Ok(decoded_header) = header_result
49:         && let Ok(encoded) = decoded_header.encode()
50:     {
51:         assert_eq!(
52:             &encoded[..],
53:             header_bytes,
54:             "re-encoded header must match original bytes"
55:         );
56:     }
57: 
58:     let Some(payload) = data.get(vb_ipc::IPC_HEADER_LEN..) else {
59:         return;
60:     };
61: 
62:     if !payload.is_empty()
63:         && let Ok(header) = header_result
64:     {
65:         let payload_len_usize = header.payload_len as usize;
66:         let result = decode_frame_payload(&header, payload);
67:         match result {
68:             Ok(decoded) => {
69:                 assert!(
70:                     payload.len() == payload_len_usize,
71:                     "decode must fail when payload len mismatches header"
72:                 );
73:                 match decoded {
74:                     vb_ipc::IpcPayload::SubmitRun(p) | vb_ipc::IpcPayload::SubmitRunInline(p) => {
75:                         let _ = p.run_id;
76:                         let _ = p.workflow;
77:                     }
78:                     vb_ipc::IpcPayload::CancelRun { run_id }
79:                     | vb_ipc::IpcPayload::InspectRun { run_id }
80:                     | vb_ipc::IpcPayload::ListEvents { run_id, .. }
81:                     | vb_ipc::IpcPayload::DrainTrace { run_id, .. } => {
82:                         let _ = run_id;
83:                     }
84:                     vb_ipc::IpcPayload::AnswerAsk { run_id, ticket, .. } => {
85:                         let _ = run_id;
86:                         let _ = ticket;
87:                     }
88:                     vb_ipc::IpcPayload::CompleteAction { run_id, ticket, .. }
89:                     | vb_ipc::IpcPayload::FailAction { run_id, ticket, .. } => {
90:                         let _ = run_id;
91:                         let _ = ticket;
92:                     }
93:                     vb_ipc::IpcPayload::Health | vb_ipc::IpcPayload::Shutdown => {}
94:                     _ => {}
95:                 }
96:             }
97:             Err(e) => assert!(assert_typed_ipc_error(e)),
98:         }
99:     }
100: }
