102: pub fn fuzz_ipc_decode(data: &[u8]) {
103:     use vb_ipc::frame::decode_frame_header;
104: 
105:     if data.len() >= vb_ipc::IPC_HEADER_LEN {
106:         let mut header_bytes = [0u8; vb_ipc::IPC_HEADER_LEN];
107:         header_bytes.copy_from_slice(&data[..vb_ipc::IPC_HEADER_LEN]);
108: 
109:         let bounds: &[usize] = &[0, 1, 16, 256, 1024, 65536, 1_048_576];
110:         for &b in bounds {
111:             if let Some(max) = std::num::NonZeroUsize::new(b) {
112:                 let _ = vb_ipc::IpcFrameHeader::decode(
113:                     &header_bytes,
114:                     vb_ipc::MaxPayloadBytes::new(max),
115:                 );
116:             }
117:         }
118: 
119:         let _ = decode_frame_header(&header_bytes);
120:     }
121: 
122:     for len in 0..vb_ipc::IPC_HEADER_LEN {
123:         if data.len() >= len {
124:             let mut bytes = [0u8; vb_ipc::IPC_HEADER_LEN];
125:             let end = len.min(data.len());
126:             bytes[..end].copy_from_slice(&data[..end]);
127:             let _ = vb_ipc::IpcFrameHeader::decode(&bytes, vb_ipc::MaxPayloadBytes::DEFAULT);
128:         }
129:     }
130: }
