132: pub fn fuzz_ipc_frame_boundary(data: &[u8]) {
133:     use vb_ipc::frame::{decode_frame_header, validate_frame_magic};
134:     use vb_ipc::{IPC_HEADER_LEN, IpcError, MaxPayloadBytes};
135: 
136:     if data.is_empty() {
137:         return;
138:     }
139: 
140:     let magic_result = validate_frame_magic(data);
141:     if data.len() < 4 {
142:         assert!(
143:             matches!(magic_result, Err(IpcError::HeaderDecodeFailed)),
144:             "truncated frame (< 4 bytes) must return HeaderDecodeFailed"
145:         );
146:         return;
147:     }
148: 
149:     if magic_result.is_err() {
150:         assert!(
151:             matches!(
152:                 magic_result,
153:                 Err(IpcError::InvalidMagic { .. }) | Err(IpcError::HeaderDecodeFailed)
154:             ),
155:             "wrong magic must return InvalidMagic or HeaderDecodeFailed"
156:         );
157:         return;
158:     }
159: 
160:     if data.len() < IPC_HEADER_LEN {
161:         return;
162:     }
163: 
164:     let mut header_bytes = [0u8; IPC_HEADER_LEN];
165:     header_bytes.copy_from_slice(&data[..IPC_HEADER_LEN]);
166: 
167:     let Some(max_payload_nz) = std::num::NonZeroUsize::new(65536) else {
168:         return;
169:     };
170:     let max_payload = MaxPayloadBytes::new(max_payload_nz);
171:     let header_result = vb_ipc::IpcFrameHeader::decode(&header_bytes, max_payload);
172: 
173:     match header_result {
174:         Ok(header) => {
175:             let payload = data.get(IPC_HEADER_LEN..).unwrap_or(&[]);
176:             let Ok(expected_len) = usize::try_from(header.payload_len) else {
177:                 return;
178:             };
179:             if payload.len() != expected_len && !payload.is_empty() {}
180:         }
181:         Err(e) => {
182:             assert!(assert_typed_ipc_error(e));
183:         }
184:     }
185: 
186:     if data.len() >= IPC_HEADER_LEN {
187:         let _ = decode_frame_header(&header_bytes);
188:     }
189: }
