16:     Disconnected,
17:     /// Payload exceeds the configured frame limit.
18:     #[error("ingress payload is too large: actual={actual}, limit={limit}")]
19:     PayloadTooLarge {
20:         /// Actual payload bytes.
21:         actual: usize,
22:         /// Configured limit.
23:         limit: usize,
24:     },
25:     /// Frame magic did not match `VBLT`.
26:     #[error("invalid IPC frame magic: actual={actual:#010x}")]
27:     InvalidMagic {
28:         /// Decoded magic value.
29:         actual: u32,
30:     },
31:     /// Frame version is not supported by this crate.
32:     #[error("unsupported IPC frame version: actual={actual}")]
33:     UnsupportedVersion {
34:         /// Decoded version value.
