114:     /// Returns the stable diagnostic code for this error.
115:     #[must_use]
116:     pub const fn diagnostic_code(&self) -> DiagnosticCode {
117:         match self {
118:             Self::Full => Self::FULL_CODE,
119:             Self::Disconnected => Self::DISCONNECTED_CODE,
120:             Self::PayloadTooLarge { .. } => Self::PAYLOAD_TOO_LARGE_CODE,
121:             Self::InvalidMagic { .. } => Self::INVALID_MAGIC_CODE,
122:             Self::UnsupportedVersion { .. } => Self::UNSUPPORTED_VERSION_CODE,
123:             Self::UnknownCommand(_) => Self::UNKNOWN_COMMAND_CODE,
124:             Self::ReservedNonZero { .. } => Self::RESERVED_NON_ZERO_CODE,
125:             Self::PayloadLengthMismatch { .. } => Self::PAYLOAD_LENGTH_MISMATCH_CODE,
126:             Self::HeaderEncodeFailed => Self::HEADER_ENCODE_FAILED_CODE,
127:             Self::HeaderDecodeFailed => Self::HEADER_DECODE_FAILED_CODE,
128:             Self::PayloadLengthOutOfRange { .. } => Self::PAYLOAD_LENGTH_OUT_OF_RANGE_CODE,
129:             Self::PayloadEncodeFailed => Self::PAYLOAD_ENCODE_FAILED_CODE,
130:             Self::PayloadDecodeFailed => Self::PAYLOAD_DECODE_FAILED_CODE,
131:             Self::ResponseDecodeFailed => Self::RESPONSE_DECODE_FAILED_CODE,
132:         }
133:     }
