135:     /// Returns the stable section 17 runtime code when this IPC error has a direct mapping.
136:     #[must_use]
137:     pub const fn runtime_code(&self) -> Option<&'static str> {
138:         match self {
139:             Self::Full => Some(Self::QUEUE_FULL_RUNTIME_CODE),
140:             Self::PayloadTooLarge { .. } | Self::PayloadLengthOutOfRange { .. } => {
141:                 Some(Self::IPC_PAYLOAD_TOO_LARGE_RUNTIME_CODE)
142:             }
143:             Self::InvalidMagic { .. }
144:             | Self::UnsupportedVersion { .. }
145:             | Self::UnknownCommand(_)
146:             | Self::ReservedNonZero { .. }
147:             | Self::PayloadLengthMismatch { .. }
148:             | Self::HeaderDecodeFailed
149:             | Self::PayloadDecodeFailed
150:             | Self::ResponseDecodeFailed => Some(Self::IPC_FRAME_INVALID_RUNTIME_CODE),
151:             Self::Disconnected | Self::HeaderEncodeFailed | Self::PayloadEncodeFailed => None,
152:         }
153:     }
154: }
