156: /// Converts a u32 payload length to usize, returning an error if it doesn't fit.
157: ///
158: /// On 64-bit platforms this is always valid since usize is 64-bit and u32 fits.
159: /// On 32-bit platforms, payloads larger than `u32::MAX` would fail the conversion,
160: /// but such payloads cannot be represented in the IPC frame anyway (payload_len is u32).
161: pub(crate) fn u32_to_usize(value: u32) -> Result<usize, IpcError> {
162:     match usize::try_from(value) {
163:         Ok(converted) => Ok(converted),
164:         Err(_) => Err(IpcError::PayloadLengthOutOfRange { actual: value }),
165:     }
166: }
